void check(Solution& solution) {
    assert(solution.platesBetweenCandles("**|**|***|", {{2,5},{5,9}}) == vector<int>{2, 3});
    assert(solution.platesBetweenCandles("***||***", {{0,5},{2,4}}) == vector<int>{0, 0});
    assert(solution.platesBetweenCandles("*|*|*|*|*|*|*|", {{0,7},{1,6},{2,5}}) == vector<int>{3, 2, 1});
    assert(solution.platesBetweenCandles("|||***|||", {{0,8},{1,7},{2,6}}) == vector<int>{3, 3, 3});
    assert(solution.platesBetweenCandles("||*|*|*|*|*|*|", {{0,10},{1,9},{2,8},{3,7}}) == vector<int>{4, 4, 2, 2});
    assert(solution.platesBetweenCandles("|||****|****|****||", {{0,10},{5,15},{1,4}}) == vector<int>{4, 4, 0});
    assert(solution.platesBetweenCandles("*|*|*|*|*|", {{0,5},{1,4}}) == vector<int>{2, 1});
    assert(solution.platesBetweenCandles("|*|*|*|*|*|*|*|*|*|*|", {{0,10},{1,9},{2,8},{3,7}}) == vector<int>{5, 3, 3, 1});
    assert(solution.platesBetweenCandles("|||*****|||", {{0,2},{3,8},{7,10}}) == vector<int>{0, 0, 0});
    assert(solution.platesBetweenCandles("*|*|*|*|*|*|*|*|*|*|*|", {{0,11},{1,10},{2,9},{3,8}}) == vector<int>{5, 4, 3, 2});
    assert(solution.platesBetweenCandles("*|*|*|*|*|*|*|*|*|*|", {{0,10},{1,9},{2,8},{3,7}}) == vector<int>{4, 4, 2, 2});
    assert(solution.platesBetweenCandles("***|**|*****|**||**|*", {{1,17},{4,5},{14,17},{5,11},{15,16}}) == vector<int>{9, 0, 0, 0, 0});
    assert(solution.platesBetweenCandles("|**|*|**|****|**, {{0,20},{3,10},{10,15}}) == vector<int>Error: Solution.platesBetweenCandles() missing 1 required positional argument: 's');
    assert(solution.platesBetweenCandles("***||****|**|", {{0,4},{5,8},{9,11}}) == vector<int>{0, 0, 0});
}

