public static void check(Solution solution) {
    assert Arrays.equals(solution.platesBetweenCandles("**|**|***|", new int[]{{2,5},{5,9}}), new int[]{2, 3});
    assert Arrays.equals(solution.platesBetweenCandles("***||***", new int[]{{0,5},{2,4}}), new int[]{0, 0});
    assert Arrays.equals(solution.platesBetweenCandles("*|*|*|*|*|*|*|", new int[]{{0,7},{1,6},{2,5}}), new int[]{3, 2, 1});
    assert Arrays.equals(solution.platesBetweenCandles("|||***|||", new int[]{{0,8},{1,7},{2,6}}), new int[]{3, 3, 3});
    assert Arrays.equals(solution.platesBetweenCandles("||*|*|*|*|*|*|", new int[]{{0,10},{1,9},{2,8},{3,7}}), new int[]{4, 4, 2, 2});
    assert Arrays.equals(solution.platesBetweenCandles("|||****|****|****||", new int[]{{0,10},{5,15},{1,4}}), new int[]{4, 4, 0});
    assert Arrays.equals(solution.platesBetweenCandles("*|*|*|*|*|", new int[]{{0,5},{1,4}}), new int[]{2, 1});
    assert Arrays.equals(solution.platesBetweenCandles("|*|*|*|*|*|*|*|*|*|*|", new int[]{{0,10},{1,9},{2,8},{3,7}}), new int[]{5, 3, 3, 1});
    assert Arrays.equals(solution.platesBetweenCandles("|||*****|||", new int[]{{0,2},{3,8},{7,10}}), new int[]{0, 0, 0});
    assert Arrays.equals(solution.platesBetweenCandles("*|*|*|*|*|*|*|*|*|*|*|", new int[]{{0,11},{1,10},{2,9},{3,8}}), new int[]{5, 4, 3, 2});
    assert Arrays.equals(solution.platesBetweenCandles("*|*|*|*|*|*|*|*|*|*|", new int[]{{0,10},{1,9},{2,8},{3,7}}), new int[]{4, 4, 2, 2});
    assert Arrays.equals(solution.platesBetweenCandles("***|**|*****|**||**|*", new int[]{{1,17},{4,5},{14,17},{5,11},{15,16}}), new int[]{9, 0, 0, 0, 0});
    assert Arrays.equals(solution.platesBetweenCandles("|**|*|**|****|**, new int[]{{0,20},{3,10},{10,15}}), Error: Solution.platesBetweenCandles() missing 1 required positional argument: 's');
    assert Arrays.equals(solution.platesBetweenCandles("***||****|**|", new int[]{{0,4},{5,8},{9,11}}), new int[]{0, 0, 0});
}

