    console.assert(JSON.stringify(candidate("*|*|*|*|*|", [[0,5],[1,4]])) === JSON.stringify([2, 1]));
    console.assert(JSON.stringify(candidate("|*|*|*|*|*|*|*|*|*|*|", [[0,10],[1,9],[2,8],[3,7]])) === JSON.stringify([5, 3, 3, 1]));
    console.assert(JSON.stringify(candidate("|||*****|||", [[0,2],[3,8],[7,10]])) === JSON.stringify([0, 0, 0]));
    console.assert(JSON.stringify(candidate("*|*|*|*|*|*|*|*|*|*|*|", [[0,11],[1,10],[2,9],[3,8]])) === JSON.stringify([5, 4, 3, 2]));
    console.assert(JSON.stringify(candidate("*|*|*|*|*|*|*|*|*|*|", [[0,10],[1,9],[2,8],[3,7]])) === JSON.stringify([4, 4, 2, 2]));
    console.assert(JSON.stringify(candidate("***|**|*****|**||**|*", [[1,17],[4,5],[14,17],[5,11],[15,16]])) === JSON.stringify([9, 0, 0, 0, 0]));
